<script setup lang="ts">
import {computed} from 'vue';
import type {Configuration,Database,Placement,StorageBindings} from '../shared/types';
import {coolingInputs,headerPowered} from '../shared/cooling';
import {mapStorageBindings} from '../shared/storage-bindings';
const props=defineProps<{configuration:Configuration;placement?:Placement;db:Database}>();
const emit=defineEmits<{'update:bindings':[value:StorageBindings]}>();
const part=(id:string)=>props.db.components.find(c=>c.id===id);
const rows=computed(()=>(props.placement?[props.placement]:props.configuration.placements).filter(p=>!!part(p.componentId)&&(part(p.componentId)?.specs.coolingDevices?.length||p.coolingConnections?.length)));
function options(p:Placement){return props.configuration.placements.filter(provider=>provider.id!==p.id&&provider.quantity===1).flatMap(provider=>(part(provider.componentId)?.specs.coolingHeaders||[]).map(header=>({title:`${part(provider.componentId)?.name} / ${header.name||header.id} · ${header.maxCurrentA??'?'} A`,value:JSON.stringify([provider.id,header.id])})));}
function recorded(p:Placement,id:string,index:number){return p.coolingConnections?.find(c=>c.deviceId===id&&c.deviceIndex===index);}
function value(p:Placement,id:string,index:number){const c=recorded(p,id,index);return c?JSON.stringify([c.headerPlacementId,c.headerId]):null;}
function choices(p:Placement,id:string,index:number){const choices=options(p),saved=value(p,id,index);if(saved&&!choices.some(c=>c.value===saved))choices.push({title:'Recorded header (missing or unavailable)',value:saved});return choices;}
function obsolete(p:Placement){const inputs=coolingInputs(part(p.componentId)!,p.quantity);return (p.coolingConnections||[]).filter(c=>!inputs.some(i=>i.device.id===c.deviceId&&i.deviceIndex===c.deviceIndex));}
function removeObsolete(p:Placement){const old=new Set(obsolete(p));p.coolingConnections=(p.coolingConnections||[]).filter(c=>!old.has(c));emit('update:bindings',mapStorageBindings(p));}
function select(p:Placement,id:string,index:number,input:unknown){p.coolingConnections=(p.coolingConnections||[]).filter(c=>c.deviceId!==id||c.deviceIndex!==index);if(typeof input==='string'){const [headerPlacementId,headerId]=JSON.parse(input) as [string,string];p.coolingConnections.push({deviceId:id,deviceIndex:index,headerPlacementId,headerId});}emit('update:bindings',mapStorageBindings(p));}
</script>
<template><section v-if="rows.length" class="control-stack mt-6"><h3>Fan and pump wiring</h3><p class="form-hint">Choose power/control headers for each motor. Separate SATA/peripheral motor power must also be connected. Header and shared current budgets are checked in the compatibility report.</p><div v-for="p in rows" :key="p.id" class="panel pa-4 control-stack"><h4>{{part(p.componentId)?.name}} × {{p.quantity}}</h4><v-alert v-if="obsolete(p).length" type="warning" variant="tonal">{{obsolete(p).length}} saved routes no longer match the motors/counts. <v-btn variant="text" @click="removeObsolete(p)">Clear obsolete cooling routes</v-btn></v-alert><div v-for="input in coolingInputs(part(p.componentId)!,p.quantity)" :key="input.device.id+':'+input.deviceIndex" class="form-grid"><div><strong>{{input.device.name||input.device.kind}} {{input.deviceIndex}}</strong><p class="form-hint">{{input.device.control||'Control unknown'}} · {{input.device.powerConnector||'Power unknown'}}<br>{{headerPowered(input.device)?'Motor powered by this header':'Control/RPM only; motor uses separate power'}}</p></div><v-select :model-value="value(p,input.device.id,input.deviceIndex)" :label="`${input.device.id} / ${input.deviceIndex} header`" :items="choices(p,input.device.id,input.deviceIndex)" clearable @update:model-value="v=>select(p,input.device.id,input.deviceIndex,v)" /></div></div></section></template>
